import json,httpx,time
from pathlib import Path
c=httpx.Client(base_url='http://127.0.0.1:8000',trust_env=False,timeout=90);ctx=json.loads(Path('.runtime/test-context.json').read_text());local=json.loads(Path('.runtime/local-run.json').read_text());results={}
def req(m,p,**kw):
 r=c.request(m,p,**kw);r.raise_for_status();return r.json()
rid=ctx['run'];sid=req('GET','/research-square/import-status/'+rid)['research_public_id'];results['pin']=req('POST','/research-square/researches/'+sid+'/pin',json={'pinned':True});results['pagination']=req('GET','/research-square/researches?limit=1&offset=0');results['remove']=req('DELETE','/research-square/researches/'+sid+'/import');assert req('GET','/research-runs/'+rid)['record']['status']=='completed';results['reimport']=req('POST','/research-square/publish',json={'source_run_id':rid,'model_profile_id':ctx['profile']});g=req('GET','/research-square/graph');results['personal_graph']={'nodes':len(g['nodes']),'edges':len(g['edges'])};results['personal_node']=req('GET','/research-square/community/topics/'+g['nodes'][0]['id']);g=req('GET','/research-square/openalex/graph?days=365');results['academic_graph']={'nodes':len(g['nodes']),'edges':len(g['edges'])};node=g['nodes'][0];results['academic_node']=req('GET','/research-square/openalex/topics/'+node['id']);print('GRAPH CRUD AND NODE DETAILS OK',flush=True)
for mode,q in [('openalex','请介绍'+node['name']+'关联的论文和研究趋势'),('local',node['name']+'还有哪些研究方向是我遗漏的？')]:
 results[mode+'_chat']=req('POST','/research-square/chat',json={'question':q,'data_source':mode,'model_profile_id':ctx['profile'],'days':365});print(mode,'CHAT',str(results[mode+'_chat'].get('answer'))[:200],flush=True)
results['quote_chat']=req('POST','/reading/'+local['run']+'/acceptance-context/chat',json={'question':'根据研究上下文，项目编号是什么？','quote':'资料采集 → 交叉核验 → 生成报告','model_profile_id':ctx['profile'],'scope':'report','revision':0});print('QUOTE_CHAT_OK',flush=True)
d=req('GET','/research-runs/'+local['run']);tasks=next(x['event']['tasks'] for x in reversed(d['events']) if x['event']['type'] in ['todo_list','tasks_updated']);t=tasks[0];results['task_edit']=req('PUT','/research-runs/'+local['run']+'/tasks',json={'tasks':[{'id':t['id'],'title':'核验星桥项目编号','intent':'仅根据本地资料确认XQ-8472编号。'},{'title':'核验星桥三个阶段','intent':'仅根据本地资料说明资料采集、交叉核验、生成报告三个阶段。'}]});print('TASK_EDIT_SUBMITTED',flush=True)
Path('.runtime/graph-and-context-results.json').write_text(json.dumps(results,ensure_ascii=False,indent=2),encoding='utf8')
